ALTER TABLE public.delivery_settings ADD COLUMN IF NOT EXISTS arrival_distance_limit_m integer NOT NULL DEFAULT 300, ADD COLUMN IF NOT EXISTS office_emergency_number text, ADD COLUMN IF NOT EXISTS crates_at_customer_enabled boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS expired_returns_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.trip_stops ADD COLUMN IF NOT EXISTS arrival_latitude numeric, ADD COLUMN IF NOT EXISTS arrival_longitude numeric, ADD COLUMN IF NOT EXISTS arrival_distance_m numeric, ADD COLUMN IF NOT EXISTS arrival_reason text, ADD COLUMN IF NOT EXISTS arrival_note text;
ALTER TABLE public.delivery_lines ADD COLUMN IF NOT EXISTS reason_code text, ADD COLUMN IF NOT EXISTS reason_note text, ADD COLUMN IF NOT EXISTS reason_photo_url text;
ALTER TABLE public.trip_expenses ADD COLUMN IF NOT EXISTS diesel_litres numeric;
CREATE TABLE public.customer_crate_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,customer_id uuid NOT NULL REFERENCES public.customers(id),trip_id uuid NOT NULL REFERENCES public.trips(id),stop_id uuid NOT NULL UNIQUE REFERENCES public.trip_stops(id),crates_left integer NOT NULL DEFAULT 0,crates_picked_up integer NOT NULL DEFAULT 0,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_crate_movements TO authenticated; GRANT ALL ON public.customer_crate_movements TO service_role;
ALTER TABLE public.customer_crate_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY crate_read ON public.customer_crate_movements FOR SELECT TO authenticated USING(company_id=public.my_company_id() AND (public._is_my_trip(trip_id) OR public.has_perm('dispatch','view')));
CREATE TABLE public.trip_expired_returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,trip_id uuid NOT NULL REFERENCES public.trips(id),stop_id uuid NOT NULL REFERENCES public.trip_stops(id),customer_id uuid NOT NULL REFERENCES public.customers(id),product_id uuid NOT NULL REFERENCES public.products(id),qty numeric NOT NULL,photo_url text NOT NULL,driver_user_id uuid NOT NULL DEFAULT auth.uid(),received_qty numeric,received_at timestamptz,office_action text,office_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trip_expired_returns TO authenticated; GRANT ALL ON public.trip_expired_returns TO service_role;
ALTER TABLE public.trip_expired_returns ENABLE ROW LEVEL SECURITY;
CREATE POLICY expired_read ON public.trip_expired_returns FOR SELECT TO authenticated USING(company_id=public.my_company_id() AND (public._is_my_trip(trip_id) OR public.has_perm('dispatch','view') OR public.has_perm('finance','view')));
CREATE TABLE public.expired_scrap_stock(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,unit_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id),expired_return_id uuid NOT NULL UNIQUE REFERENCES public.trip_expired_returns(id),qty numeric NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.expired_scrap_stock TO authenticated; GRANT ALL ON public.expired_scrap_stock TO service_role;
ALTER TABLE public.expired_scrap_stock ENABLE ROW LEVEL SECURITY;
CREATE POLICY scrap_read ON public.expired_scrap_stock FOR SELECT TO authenticated USING(company_id=public.my_company_id() AND public.has_perm('dispatch','view'));
CREATE OR REPLACE FUNCTION public.delivery_gap_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='delivery_settings' THEN IF NEW.arrival_distance_limit_m<0 THEN RAISE EXCEPTION 'Distance cannot be negative'; END IF;
 ELSIF TG_TABLE_NAME='customer_crate_movements' THEN IF NEW.crates_left<0 OR NEW.crates_picked_up<0 THEN RAISE EXCEPTION 'Crates cannot be negative'; END IF;
 ELSIF TG_TABLE_NAME='trip_expired_returns' THEN IF NEW.qty<=0 OR trim(NEW.photo_url)='' OR (NEW.received_qty IS NOT NULL AND NEW.received_qty<0) THEN RAISE EXCEPTION 'Quantity and photo required'; END IF; IF NEW.office_action IS NOT NULL AND NEW.office_action NOT IN ('credit_note','no_credit','replace') THEN RAISE EXCEPTION 'Invalid office action'; END IF;
 ELSIF TG_TABLE_NAME='expired_scrap_stock' THEN IF NEW.qty<0 THEN RAISE EXCEPTION 'Quantity cannot be negative'; END IF;
 ELSIF TG_TABLE_NAME='trip_expenses' THEN IF NEW.diesel_litres IS NOT NULL AND (NEW.diesel_litres<=0 OR lower(NEW.expense_type)<>'diesel') THEN RAISE EXCEPTION 'Diesel litres must be positive'; END IF;
 END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER delivery_gap_settings BEFORE UPDATE ON public.delivery_settings FOR EACH ROW EXECUTE FUNCTION public.delivery_gap_validate();
CREATE TRIGGER delivery_gap_crates BEFORE INSERT OR UPDATE ON public.customer_crate_movements FOR EACH ROW EXECUTE FUNCTION public.delivery_gap_validate();
CREATE TRIGGER delivery_gap_expired BEFORE INSERT OR UPDATE ON public.trip_expired_returns FOR EACH ROW EXECUTE FUNCTION public.delivery_gap_validate();
CREATE TRIGGER delivery_gap_scrap BEFORE INSERT OR UPDATE ON public.expired_scrap_stock FOR EACH ROW EXECUTE FUNCTION public.delivery_gap_validate();
CREATE OR REPLACE FUNCTION public.record_stop_arrival(p_stop_id uuid,p_latitude numeric DEFAULT NULL,p_longitude numeric DEFAULT NULL,p_reason text DEFAULT NULL,p_note text DEFAULT NULL) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops;o public.orders;d numeric; BEGIN
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id FOR UPDATE; IF s.id IS NULL OR NOT public._is_my_trip(s.trip_id) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=s.order_id;
 IF p_latitude IS NOT NULL AND p_longitude IS NOT NULL AND o.delivery_latitude IS NOT NULL AND o.delivery_longitude IS NOT NULL THEN d=round((6371000*2*asin(least(1,sqrt(power(sin(radians((p_latitude-o.delivery_latitude)::double precision)/2),2)+cos(radians(o.delivery_latitude::double precision))*cos(radians(p_latitude::double precision))*power(sin(radians((p_longitude-o.delivery_longitude)::double precision)/2),2)))))::numeric); END IF;
 UPDATE public.trip_stops SET arrived_at=coalesce(arrived_at,now()),arrival_latitude=p_latitude,arrival_longitude=p_longitude,arrival_distance_m=d,arrival_reason=p_reason,arrival_note=p_note WHERE id=p_stop_id;
 RETURN d; END $$;
CREATE OR REPLACE FUNCTION public.record_customer_crates(p_stop_id uuid,p_left integer,p_picked_up integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops;o public.orders;v uuid; BEGIN
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id; IF s.id IS NULL OR NOT public._is_my_trip(s.trip_id) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=s.order_id; IF NOT coalesce((SELECT crates_at_customer_enabled FROM public.delivery_settings WHERE company_id=o.company_id),false) THEN RAISE EXCEPTION 'Crates switched off'; END IF;
 INSERT INTO public.customer_crate_movements(company_id,customer_id,trip_id,stop_id,crates_left,crates_picked_up) VALUES(o.company_id,o.customer_id,s.trip_id,s.id,p_left,p_picked_up) ON CONFLICT(stop_id) DO UPDATE SET crates_left=excluded.crates_left,crates_picked_up=excluded.crates_picked_up RETURNING id INTO v; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.record_expired_return(p_stop_id uuid,p_product_id uuid,p_qty numeric,p_photo_url text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops;o public.orders;v uuid; BEGIN
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id; IF s.id IS NULL OR NOT public._is_my_trip(s.trip_id) THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT * INTO o FROM public.orders WHERE id=s.order_id;
 IF NOT coalesce((SELECT expired_returns_enabled FROM public.delivery_settings WHERE company_id=o.company_id),false) THEN RAISE EXCEPTION 'Expired returns switched off'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=p_product_id AND company_id=o.company_id) THEN RAISE EXCEPTION 'Product not found'; END IF;
 INSERT INTO public.trip_expired_returns(company_id,trip_id,stop_id,customer_id,product_id,qty,photo_url) VALUES(o.company_id,s.trip_id,s.id,o.customer_id,p_product_id,p_qty,p_photo_url) RETURNING id INTO v;
 PERFORM public._photo_register(o.company_id,p_photo_url,'delivery','trip_expired_returns',v,s.trip_id,o.customer_id,o.id,NULL,auth.uid(),now()); RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.add_delivery_expense(p_trip_id uuid,p_type text,p_amount numeric,p_bill_photo_url text DEFAULT NULL,p_note text DEFAULT NULL,p_litres numeric DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid; BEGIN
 IF p_litres IS NOT NULL AND (p_litres<=0 OR lower(p_type)<>'diesel') THEN RAISE EXCEPTION 'Diesel litres must be positive'; END IF;
 v=public.add_trip_expense(p_trip_id,p_type,p_amount,p_bill_photo_url,p_note); UPDATE public.trip_expenses SET diesel_litres=p_litres WHERE id=v;
 UPDATE public.trips SET fuel_litres=(SELECT sum(diesel_litres) FROM public.trip_expenses WHERE trip_id=p_trip_id),fuel_amount=(SELECT sum(amount) FROM public.trip_expenses WHERE trip_id=p_trip_id AND lower(expense_type)='diesel') WHERE id=p_trip_id; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.stop_payment_totals(p_stop_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops;o public.orders;old numeric; BEGIN
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id; IF s.id IS NULL OR NOT public._is_my_trip(s.trip_id) THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT * INTO o FROM public.orders WHERE id=s.order_id;
 SELECT coalesce(sum(b.balance),0) INTO old FROM public._open_bills(o.customer_id,o.firm_id) b WHERE NOT EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=b.ref_id AND i.order_id=o.id);
 RETURN jsonb_build_object('old_due',CASE WHEN (SELECT collect_old_dues FROM public.delivery_settings WHERE company_id=o.company_id) THEN greatest(0,old-coalesce((SELECT sum(amount) FROM public.trip_collections WHERE customer_id=o.customer_id AND against_old_dues AND NOT confirmed),0)) ELSE 0 END); END $$;
CREATE OR REPLACE FUNCTION public.collect_stop_payment(p_stop_id uuid,p_mode text,p_amount numeric,p_reference text DEFAULT NULL,p_photo_url text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops;o public.orders;current_due numeric;current_part numeric;v uuid; BEGIN
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id FOR UPDATE; IF s.id IS NULL OR NOT public._is_my_trip(s.trip_id) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=s.order_id; IF p_amount<=0 OR p_mode NOT IN ('cash','upi','bank','cheque') THEN RAISE EXCEPTION 'Enter a valid amount and mode'; END IF;
 SELECT greatest(0,coalesce(sum((ol.line_total+ol.deposit_total)*dl.delivered_qty/nullif(ol.qty,0)),o.grand_total)-greatest(o.amount_paid,coalesce((SELECT sum(amount) FROM public.trip_collections WHERE order_id=o.id AND NOT against_old_dues),0))) INTO current_due FROM public.order_lines ol LEFT JOIN public.delivery_lines dl ON dl.order_line_id=ol.id AND dl.stop_id=s.id WHERE ol.order_id=o.id;
 current_part=least(p_amount,current_due); IF p_mode='cheque' AND p_photo_url IS NULL THEN RAISE EXCEPTION 'Add cheque photo'; END IF;
 IF current_part>0 THEN v=public.record_collection(p_stop_id,p_mode,current_part,p_reference,p_photo_url); END IF;
 IF p_amount>current_part THEN
 IF NOT (SELECT collect_old_dues FROM public.delivery_settings WHERE company_id=o.company_id) THEN RAISE EXCEPTION 'Old dues collection switched off'; END IF;
 INSERT INTO public.trip_collections(trip_id,stop_id,customer_id,mode,amount,reference,photo_url,collected_by,against_old_dues) VALUES(s.trip_id,s.id,o.customer_id,p_mode,p_amount-current_part,p_reference,p_photo_url,auth.uid(),true) RETURNING id INTO v; END IF; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.my_trip_account(p_month date,p_offset integer DEFAULT 0,p_limit integer DEFAULT 30) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 WITH all_trips AS(SELECT t.* FROM public.trips t WHERE t.driver_user_id=auth.uid() AND public.my_session_is_valid() AND t.trip_date>=date_trunc('month',p_month)::date AND t.trip_date<(date_trunc('month',p_month)+interval '1 month')::date), rows AS(SELECT t.id,t.trip_no,t.trip_date,t.status,v.reg_no,t.settled_at,t.cash_received,t.cash_expected,t.settle_note,greatest(0,coalesce(t.end_odometer-t.start_odometer,0)) km,
 (SELECT count(*) FROM public.trip_stops WHERE trip_id=t.id AND status IN ('delivered','partial')) done,(SELECT count(*) FROM public.trip_stops WHERE trip_id=t.id AND status='failed') failed,
 coalesce((SELECT sum(amount) FROM public.trip_collections WHERE trip_id=t.id AND mode='cash'),0) cash,coalesce((SELECT sum(amount) FROM public.trip_collections WHERE trip_id=t.id AND mode='upi'),0) upi,coalesce((SELECT sum(amount) FROM public.trip_collections WHERE trip_id=t.id AND mode='cheque'),0) cheque,coalesce((SELECT sum(amount) FROM public.trip_collections WHERE trip_id=t.id AND mode='bank'),0) bank,
 coalesce((SELECT sum(amount) FROM public.trip_expenses WHERE trip_id=t.id),0) expenses,coalesce((SELECT sum(amount) FROM public.cash_handovers WHERE trip_id=t.id),0) handed_over FROM all_trips t LEFT JOIN public.vehicles v ON v.id=t.vehicle_id)
 SELECT jsonb_build_object('total_count',(SELECT count(*) FROM rows),'totals',(SELECT jsonb_build_object('cash',coalesce(sum(cash),0),'upi',coalesce(sum(upi),0),'cheque',coalesce(sum(cheque),0),'bank',coalesce(sum(bank),0),'expenses',coalesce(sum(expenses),0),'handed_over',coalesce(sum(handed_over),0),'km',coalesce(sum(km),0),'done',coalesce(sum(done),0),'failed',coalesce(sum(failed),0)) FROM rows),'trips',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM(SELECT * FROM rows ORDER BY trip_date DESC,id OFFSET greatest(p_offset,0) LIMIT least(greatest(p_limit,1),100)) r),'[]'::jsonb)); $$;
DO $$ DECLARE d text; BEGIN
 SELECT pg_get_functiondef('public.deliver_stop(uuid,jsonb,jsonb,text)'::regprocedure) INTO d;
 d=replace(d,'empties_returned)','empties_returned,reason_code,reason_note,reason_photo_url)');
 d=replace(d,'coalesce((v_l ->> ''empties'')::int, 0));','coalesce((v_l ->> ''empties'')::int, 0),v_l->>''reason_code'',v_l->>''reason_note'',v_l->>''reason_photo_url'');'); EXECUTE d;
 SELECT pg_get_functiondef('public.run_op(uuid,text,jsonb)'::regprocedure) INTO d;
 d=replace(d,'''confirm_trip_crates_loaded'')','''confirm_trip_crates_loaded'',''record_stop_arrival'',''record_customer_crates'',''record_expired_return'',''add_delivery_expense'',''collect_stop_payment'')');
 d=replace(d,'IF auth.uid() IS NULL THEN','PERFORM pg_advisory_xact_lock(hashtext(p_op_id::text)); IF auth.uid() IS NULL THEN'); EXECUTE d;
 SELECT pg_get_functiondef('public.trip_return_expected(uuid)'::regprocedure) INTO d;
 d=replace(d,'coalesce(t.crates_loaded,0)::numeric','greatest(0,coalesce(t.crates_loaded,0)-coalesce((SELECT sum(crates_left-crates_picked_up) FROM public.customer_crate_movements WHERE trip_id=t.id),0))::numeric');
 d=replace(d,'$function$', '$function$');
 d=replace(d,chr(10)||'$function$',chr(10)||' union all select e.product_id,''expired'',sum(e.qty) from public.trip_expired_returns e where e.trip_id=p_trip_id and public.has_perm(''dispatch'',''view'') group by e.product_id'||chr(10)||'$function$'); EXECUTE d;
 SELECT pg_get_functiondef('public.receive_returns(uuid,jsonb,text)'::regprocedure) INTO d;
 d=replace(d,'update public.trips set returns_received_at = now() where id = p_trip_id;', 'for l in select * from jsonb_array_elements(p_lines) where value->>''kind''=''expired'' loop
 INSERT INTO public.expired_scrap_stock(company_id,unit_id,product_id,expired_return_id,qty) SELECT v_t.company_id,v_t.unit_id,e.product_id,e.id,case when coalesce((l->>''expected'')::numeric,0)>0 then e.qty*coalesce((l->>''actual'')::numeric,0)/(l->>''expected'')::numeric else 0 end FROM public.trip_expired_returns e WHERE e.trip_id=p_trip_id AND e.product_id=(l->>''product_id'')::uuid ON CONFLICT(expired_return_id) DO NOTHING;
 UPDATE public.trip_expired_returns e SET received_qty=x.qty,received_at=now(),updated_at=now() FROM public.expired_scrap_stock x WHERE x.expired_return_id=e.id AND e.trip_id=p_trip_id;
 end loop; update public.trips set returns_received_at = now() where id = p_trip_id;'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.delivery_gap_validate() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.record_stop_arrival(uuid,numeric,numeric,text,text),public.record_customer_crates(uuid,integer,integer),public.record_expired_return(uuid,uuid,numeric,text),public.add_delivery_expense(uuid,text,numeric,text,text,numeric),public.stop_payment_totals(uuid),public.collect_stop_payment(uuid,text,numeric,text,text),public.my_trip_account(date,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_stop_arrival(uuid,numeric,numeric,text,text),public.record_customer_crates(uuid,integer,integer),public.record_expired_return(uuid,uuid,numeric,text),public.add_delivery_expense(uuid,text,numeric,text,text,numeric),public.stop_payment_totals(uuid),public.collect_stop_payment(uuid,text,numeric,text,text),public.my_trip_account(date,integer,integer) TO authenticated,service_role;